query FetchMenu($id: ID!) {
      menu(id: $id) {
        id handle title isDefault
        items { id title type url resourceId tags items { id title type url resourceId tags items { id title type url resourceId tags items { id title type url resourceId tags items { id } } } } }
      }
    }

mutation DeleteMenu($id: ID!) {
            menuDelete(id: $id) {
              deletedMenuId
              userErrors { field message }
            }
          }
